real_t algorithm_memcpy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        if (sizeof(real_t) == sizeof(double)) {
            const double *src = (const double *)(const void *)x;
            double *dst = (double *)(void *)y;
            size_t n = (size_t)LEN_1D;

            while (n > 0) {
                size_t vl = __riscv_vsetvl_e64m8(n);
                vfloat64m8_t v = __riscv_vle64_v_f64m8(src, vl);
                __riscv_vse64_v_f64m8(dst, v, vl);
                src += vl;
                dst += vl;
                n -= vl;
            }
        } else if (sizeof(real_t) == sizeof(float)) {
            const float *src = (const float *)(const void *)x;
            float *dst = (float *)(void *)y;
            size_t n = (size_t)LEN_1D;

            while (n > 0) {
                size_t vl = __riscv_vsetvl_e32m8(n);
                vfloat32m8_t v = __riscv_vle32_v_f32m8(src, vl);
                __riscv_vse32_v_f32m8(dst, v, vl);
                src += vl;
                dst += vl;
                n -= vl;
            }
        } else {
            for (Index_type i = 0; i < LEN_1D; ++i) {
                y[i] = x[i];
            }
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = x[i];
        }
#endif
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

