real_t algorithm_memset(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t val = 1.42;

#if defined(__riscv_vector)
    if (sizeof(real_t) == sizeof(double)) {
        const double v = (double)val;
        for (int nl = 0; nl < iterations; nl++) {
            double *ptr = (double *)x;
            size_t cnt = (size_t)LEN_1D;

            __asm__ volatile (
                "beqz   %[cnt], 2f\n\t"
                "mv     t0, %[cnt]\n\t"
                "mv     t1, %[ptr]\n\t"
                "vsetvli t2, t0, e64, m8, ta, ma\n\t"
                "vfmv.v.f v8, %[val]\n"
                "1:\n\t"
                "slli   t3, t2, 3\n\t"
                "vse64.v v8, (t1)\n\t"
                "sub    t0, t0, t2\n\t"
                "add    t1, t1, t3\n\t"
                "beqz   t0, 2f\n\t"
                "vsetvli t2, t0, e64, m8, ta, ma\n\t"
                "j      1b\n"
                "2:\n\t"
                :
                : [ptr] "r" (ptr), [cnt] "r" (cnt), [val] "f" (v)
                : "t0", "t1", "t2", "t3", "memory"
            );

            dummy(x, NULL, NULL, NULL, NULL, val);
        }

        gettimeofday(&func_args->t2, NULL);
        return calc_checksum(__func__);
    }

    if (sizeof(real_t) == sizeof(float)) {
        const float v = (float)val;
        for (int nl = 0; nl < iterations; nl++) {
            float *ptr = (float *)x;
            size_t cnt = (size_t)LEN_1D;

            __asm__ volatile (
                "beqz   %[cnt], 2f\n\t"
                "mv     t0, %[cnt]\n\t"
                "mv     t1, %[ptr]\n\t"
                "vsetvli t2, t0, e32, m8, ta, ma\n\t"
                "vfmv.v.f v8, %[val]\n"
                "1:\n\t"
                "slli   t3, t2, 2\n\t"
                "vse32.v v8, (t1)\n\t"
                "sub    t0, t0, t2\n\t"
                "add    t1, t1, t3\n\t"
                "beqz   t0, 2f\n\t"
                "vsetvli t2, t0, e32, m8, ta, ma\n\t"
                "j      1b\n"
                "2:\n\t"
                :
                : [ptr] "r" (ptr), [cnt] "r" (cnt), [val] "f" (v)
                : "t0", "t1", "t2", "t3", "memory"
            );

            dummy(x, NULL, NULL, NULL, NULL, val);
        }

        gettimeofday(&func_args->t2, NULL);
        return calc_checksum(__func__);
    }
#endif

    for (int nl = 0; nl < iterations; nl++) {
        Index_type i = 0;
        for (; i + 7 < LEN_1D; i += 8) {
            x[i]     = val;
            x[i + 1] = val;
            x[i + 2] = val;
            x[i + 3] = val;
            x[i + 4] = val;
            x[i + 5] = val;
            x[i + 6] = val;
            x[i + 7] = val;
        }
        for (; i < LEN_1D; ++i) {
            x[i] = val;
        }
        dummy(x, NULL, NULL, NULL, NULL, val);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

