real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;

        Index_type i = 0;
        const real_t * __restrict__ px = x;

        for (; i + 7 < LEN_1D; i += 8) {
            s += px[i];
            s += px[i + 1];
            s += px[i + 2];
            s += px[i + 3];
            s += px[i + 4];
            s += px[i + 5];
            s += px[i + 6];
            s += px[i + 7];
        }
        for (; i < LEN_1D; ++i) {
            s += px[i];
        }

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
    y[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        real_t scan_var = 0.0;
        real_t *yp = y;
        const real_t *xp = x;
        Index_type n = LEN_1D;

        while (n >= 4) {
            yp[0] = scan_var;
            scan_var += xp[0];

            yp[1] = scan_var;
            scan_var += xp[1];

            yp[2] = scan_var;
            scan_var += xp[2];

            yp[3] = scan_var;
            scan_var += xp[3];

            xp += 4;
            yp += 4;
            n -= 4;
        }

        while (n > 0) {
            *yp++ = scan_var;
            scan_var += *xp++;
            --n;
        }

        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t half = 0.5f;
    const real_t ptiny = 1.0e-2f;
    const int loop_count = iterations / 4 + 1;

    for (int nl = 0; nl < loop_count; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            const real_t x1  = apps_x1[i];
            const real_t x2  = apps_x2[i];
            const real_t x3  = apps_x3[i];
            const real_t x4  = apps_x4[i];

            const real_t y1  = apps_y1[i];
            const real_t y2  = apps_y2[i];
            const real_t y3  = apps_y3[i];
            const real_t y4  = apps_y4[i];

            const real_t fx1 = apps_fx1[i];
            const real_t fx2 = apps_fx2[i];
            const real_t fx3 = apps_fx3[i];
            const real_t fx4 = apps_fx4[i];

            const real_t fy1 = apps_fy1[i];
            const real_t fy2 = apps_fy2[i];
            const real_t fy3 = apps_fy3[i];
            const real_t fy4 = apps_fy4[i];

            const real_t xi  = half * ( x1  + x2  - x3  - x4  );
            const real_t xj  = half * ( x2  + x3  - x4  - x1  );
            const real_t yi  = half * ( y1  + y2  - y3  - y4  );
            const real_t yj  = half * ( y2  + y3  - y4  - y1  );
            const real_t fxi = half * ( fx1 + fx2 - fx3 - fx4 );
            const real_t fxj = half * ( fx2 + fx3 - fx4 - fx1 );
            const real_t fyi = half * ( fy1 + fy2 - fy3 - fy4 );
            const real_t fyj = half * ( fy2 + fy3 - fy4 - fy1 );

            const real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            const real_t dfxdx = rarea * ( fxi * yj - fxj * yi );
            const real_t dfydy = rarea * ( fyj * xi - fyi * xj );
            const real_t affine = ( fy1 + fy2 + fy3 + fy4 ) /
                                  ( y1  + y2  + y3  + y4  );

            apps_div[i] = dfxdx + dfydy + affine;
        }
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

