real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;

    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
#if defined(__riscv_vector)
        {
            Index_type i = 0;
            while (i < APPS_N1D) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t ve_old = __riscv_vle32_v_f32m8((const float *)&apps_e_old[i], vl);
                vfloat32m8_t vd     = __riscv_vle32_v_f32m8((const float *)&apps_delvc[i], vl);
                vfloat32m8_t vp     = __riscv_vle32_v_f32m8((const float *)&apps_p_old[i], vl);
                vfloat32m8_t vq     = __riscv_vle32_v_f32m8((const float *)&apps_q_old[i], vl);
                vfloat32m8_t vw     = __riscv_vle32_v_f32m8((const float *)&apps_work[i], vl);

                vfloat32m8_t vpq    = __riscv_vfadd_vv_f32m8(vp, vq, vl);
                vfloat32m8_t vt     = __riscv_vfmul_vf_f32m8(vd, 0.5f, vl);
                vt                  = __riscv_vfmul_vv_f32m8(vt, vpq, vl);
                vfloat32m8_t ve     = __riscv_vfsub_vv_f32m8(ve_old, vt, vl);
                vw                  = __riscv_vfmul_vf_f32m8(vw, 0.5f, vl);
                ve                  = __riscv_vfadd_vv_f32m8(ve, vw, vl);

                __riscv_vse32_v_f32m8((float *)&apps_e_new[i], ve, vl);
                i += (Index_type)vl;
            }
        }

        {
            Index_type i = 0;
            const float ssc_min = 1.111111e-36f;
            const float ssc_rep = 3.333333e-18f;

            while (i < APPS_N1D) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t vzero  = __riscv_vfmv_v_f_f32m8(0.0f, vl);
                vfloat32m8_t vone   = __riscv_vfmv_v_f_f32m8(1.0f, vl);

                vfloat32m8_t vd     = __riscv_vle32_v_f32m8((const float *)&apps_delvc[i], vl);
                vbool4_t m_gt       = __riscv_vmfgt_vf_f32m8_b4(vd, 0.0f, vl);
                vbool4_t m_calc     = __riscv_vmnot_m_b4(m_gt, vl);

                vfloat32m8_t vcomp  = __riscv_vle32_v_f32m8((const float *)&apps_compHalfStep[i], vl);
                vfloat32m8_t vden   = __riscv_vfadd_vf_f32m8(vcomp, 1.0f, vl);
                vfloat32m8_t vhalf  = __riscv_vfdiv_vv_f32m8(vone, vden, vl);

                vfloat32m8_t vpbvc  = __riscv_vle32_v_f32m8((const float *)&apps_pbvc[i], vl);
                vfloat32m8_t ve     = __riscv_vle32_v_f32m8((const float *)&apps_e_new[i], vl);
                vfloat32m8_t vbvc   = __riscv_vle32_v_f32m8((const float *)&apps_bvc[i], vl);
                vfloat32m8_t vph    = __riscv_vle32_v_f32m8((const float *)&apps_pHalfStep[i], vl);

                vfloat32m8_t vt1    = __riscv_vfmul_vv_f32m8(vpbvc, ve, vl);
                vfloat32m8_t vh2    = __riscv_vfmul_vv_f32m8(vhalf, vhalf, vl);
                vfloat32m8_t vt2    = __riscv_vfmul_vv_f32m8(vh2, vbvc, vl);
                vt2                 = __riscv_vfmul_vv_f32m8(vt2, vph, vl);
                vfloat32m8_t vssc   = __riscv_vfadd_vv_f32m8(vt1, vt2, vl);
                vssc                = __riscv_vfdiv_vf_f32m8(vssc, (float)rho0, vl);

                vbool4_t m_small    = __riscv_vmfle_vf_f32m8_b4(vssc, ssc_min, vl);
                vfloat32m8_t vsafe  = __riscv_vfmerge_vfm_f32m8(vssc, ssc_min, m_small, vl);
                vfloat32m8_t vsscr  = __riscv_vfsqrt_v_f32m8(vsafe, vl);
                vsscr               = __riscv_vfmerge_vfm_f32m8(vsscr, ssc_rep, m_small, vl);

                vfloat32m8_t vql    = __riscv_vle32_v_f32m8((const float *)&apps_ql_old[i], vl);
                vfloat32m8_t vqq    = __riscv_vle32_v_f32m8((const float *)&apps_qq_old[i], vl);
                vfloat32m8_t vqn    = __riscv_vfmul_vv_f32m8(vsscr, vql, vl);
                vqn                 = __riscv_vfadd_vv_f32m8(vqn, vqq, vl);

                __riscv_vse32_v_f32m8((float *)&apps_q_new[i], vzero, vl);
                __riscv_vse32_v_f32m8_m(m_calc, (float *)&apps_q_new[i], vqn, vl);

                i += (Index_type)vl;
            }
        }

        {
            Index_type i = 0;
            while (i < APPS_N1D) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t ve     = __riscv_vle32_v_f32m8((const float *)&apps_e_new[i], vl);
                vfloat32m8_t vd     = __riscv_vle32_v_f32m8((const float *)&apps_delvc[i], vl);
                vfloat32m8_t vp     = __riscv_vle32_v_f32m8((const float *)&apps_p_old[i], vl);
                vfloat32m8_t vq     = __riscv_vle32_v_f32m8((const float *)&apps_q_old[i], vl);
                vfloat32m8_t vph    = __riscv_vle32_v_f32m8((const float *)&apps_pHalfStep[i], vl);
                vfloat32m8_t vqn    = __riscv_vle32_v_f32m8((const float *)&apps_q_new[i], vl);

                vfloat32m8_t vold   = __riscv_vfadd_vv_f32m8(vp, vq, vl);
                vold                = __riscv_vfmul_vf_f32m8(vold, 3.0f, vl);
                vfloat32m8_t vnew   = __riscv_vfadd_vv_f32m8(vph, vqn, vl);
                vnew                = __riscv_vfmul_vf_f32m8(vnew, 4.0f, vl);
                vfloat32m8_t vexpr  = __riscv_vfsub_vv_f32m8(vold, vnew, vl);
                vfloat32m8_t vt     = __riscv_vfmul_vf_f32m8(vd, 0.5f, vl);
                vt                  = __riscv_vfmul_vv_f32m8(vt, vexpr, vl);
                ve                  = __riscv_vfadd_vv_f32m8(ve, vt, vl);

                __riscv_vse32_v_f32m8((float *)&apps_e_new[i], ve, vl);
                i += (Index_type)vl;
            }
        }

        {
            Index_type i = 0;
            while (i < APPS_N1D) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t ve     = __riscv_vle32_v_f32m8((const float *)&apps_e_new[i], vl);
                vfloat32m8_t vw     = __riscv_vle32_v_f32m8((const float *)&apps_work[i], vl);

                vw                  = __riscv_vfmul_vf_f32m8(vw, 0.5f, vl);
                ve                  = __riscv_vfadd_vv_f32m8(ve, vw, vl);

                vfloat32m8_t vabs   = __riscv_vfabs_v_f32m8(ve, vl);
                vbool4_t m_cut      = __riscv_vmflt_vf_f32m8_b4(vabs, (float)e_cut, vl);
                ve                  = __riscv_vfmerge_vfm_f32m8(ve, 0.0f, m_cut, vl);

                vbool4_t m_emin     = __riscv_vmflt_vf_f32m8_b4(ve, (float)emin, vl);
                ve                  = __riscv_vfmerge_vfm_f32m8(ve, (float)emin, m_emin, vl);

                __riscv_vse32_v_f32m8((float *)&apps_e_new[i], ve, vl);
                i += (Index_type)vl;
            }
        }
