real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;

#if defined(__riscv_vector)
    if (sizeof(real_t) == sizeof(float)) {
        const float f_cls     = (float)cls;
        const float f_p_cut   = (float)p_cut;
        const float f_pmin    = (float)pmin;
        const float f_eosvmax = (float)eosvmax;

        for (int nl = 0; nl < iterations / 4 + 1; nl++) {
            Index_type i = 0;

            for (; i < APPS_N1D; ) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t compression =
                    __riscv_vle32_v_f32m8((const float *)&apps_compression[i], vl);
                vfloat32m8_t bvc =
                    __riscv_vfadd_vf_f32m8(compression, 1.0f, vl);
                bvc =
                    __riscv_vfmul_vf_f32m8(bvc, f_cls, vl);

                __riscv_vse32_v_f32m8((float *)&apps_bvc[i], bvc, vl);
                i += (Index_type)vl;
            }

            i = 0;
            for (; i < APPS_N1D; ) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t bvc =
                    __riscv_vle32_v_f32m8((const float *)&apps_bvc[i], vl);
                vfloat32m8_t e_old =
                    __riscv_vle32_v_f32m8((const float *)&apps_e_old[i], vl);
                vfloat32m8_t p =
                    __riscv_vfmul_vv_f32m8(bvc, e_old, vl);

                vfloat32m8_t abs_p =
                    __riscv_vfabs_v_f32m8(p, vl);
                vbool4_t m_small =
                    __riscv_vmflt_vf_f32m8_b4(abs_p, f_p_cut, vl);

                vfloat32m8_t vnewc =
                    __riscv_vle32_v_f32m8((const float *)&apps_vnewc[i], vl);
                vbool4_t m_eos =
                    __riscv_vmfge_vf_f32m8_b4(vnewc, f_eosvmax, vl);

                vbool4_t m_neg =
                    __riscv_vmflt_vf_f32m8_b4(p, f_pmin, vl);

                vbool4_t m_zero =
                    __riscv_vmor_mm_b4(m_small, m_eos, vl);
                m_zero =
                    __riscv_vmor_mm_b4(m_zero, m_neg, vl);

                p =
                    __riscv_vfmerge_vfm_f32m8(p, f_pmin, m_zero, vl);

                __riscv_vse32_v_f32m8((float *)&apps_p_new[i], p, vl);
                i += (Index_type)vl;
            }

            dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
        }
    } else
#endif
    {
        for (int nl = 0; nl < iterations / 4 + 1; nl++) {
            for (Index_type i = 0; i < APPS_N1D; ++i) {
                apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
            }
            for (Index_type i = 0; i < APPS_N1D; ++i) {
                real_t p = apps_bvc[i] * apps_e_old[i];
                if (ABS(p) < p_cut)           p = 0.0f;
                if (apps_vnewc[i] >= eosvmax) p = 0.0f;
                if (p < pmin)                 p = pmin;
                apps_p_new[i] = p;
            }
            dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
        }
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_vol3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t vnormq = 0.0833333333333f;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t x71 = apps_x7[i] - apps_x1[i], x72 = apps_x7[i] - apps_x2[i], x74 = apps_x7[i] - apps_x4[i];
            real_t x30 = apps_x3[i] - apps_x0[i], x50 = apps_x5[i] - apps_x0[i], x60 = apps_x6[i] - apps_x0[i];
            real_t y71 = apps_y7[i] - apps_y1[i], y72 = apps_y7[i] - apps_y2[i], y74 = apps_y7[i] - apps_y4[i];
            real_t y30 = apps_y3[i] - apps_y0[i], y50 = apps_y5[i] - apps_y0[i], y60 = apps_y6[i] - apps_y0[i];
            real_t z71 = apps_z7[i] - apps_z1[i], z72 = apps_z7[i] - apps_z2[i], z74 = apps_z7[i] - apps_z4[i];
            real_t z30 = apps_z3[i] - apps_z0[i], z50 = apps_z5[i] - apps_z0[i], z60 = apps_z6[i] - apps_z0[i];
            real_t xps = x71 + x60, yps = y71 + y60, zps = z71 + z60;
            real_t cyz = y72*z30 - z72*y30, czx = z72*x30 - x72*z30, cxy = x72*y30 - y72*x30;
            real_t v = xps*cyz + yps*czx + zps*cxy;
            xps = x72 + x50; yps = y72 + y50; zps = z72 + z50;
            cyz = y74*z60 - z74*y60; czx = z74*x60 - x74*z60; cxy = x74*y60 - y74*x60;
            v += xps*cyz + yps*czx + zps*cxy;
            xps = x74 + x30; yps = y74 + y30; zps = z74 + z30;
            cyz = y71*z50 - z71*y50; czx = z71*x50 - x71*z50; cxy = x71*y50 - y71*x50;
            v += xps*cyz + yps*czx + zps*cxy;
            apps_vol[i] = v * vnormq;
        }
        dummy(apps_vol, NULL, NULL, NULL, NULL, vnormq);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

