real_t lcals_planckian(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

#if defined(__riscv_vector)
    if (sizeof(real_t) == sizeof(float)) {
        float *yp = (float *)y;
        float *wp = (float *)w;
        const float *up = (const float *)u;
        const float *vp = (const float *)v;
        const float *xp = (const float *)x;
        const size_t n = (size_t)LEN_1D;

        for (int nl = 0; nl < iterations; nl++) {
            size_t i = 0;

            while (i < n) {
                size_t vl = __riscv_vsetvl_e32m8(n - i);

                vfloat32m8_t vu = __riscv_vle32_v_f32m8(up + i, vl);
                vfloat32m8_t vv = __riscv_vle32_v_f32m8(vp + i, vl);
                vfloat32m8_t vy = __riscv_vfdiv_vv_f32m8(vu, vv, vl);

                __riscv_vse32_v_f32m8(yp + i, vy, vl);
                i += vl;
            }

            i = 0;
            while (i < n) {
                enum { PLANCK_CHUNK = 256 };
                float denom[PLANCK_CHUNK];

                size_t request = n - i;
                if (request > (size_t)PLANCK_CHUNK) {
                    request = (size_t)PLANCK_CHUNK;
                }

                size_t vl = __riscv_vsetvl_e32m8(request);

                size_t j = 0;
                for (; j + 3 < vl; j += 4) {
                    denom[j]     = expf(yp[i + j])     - 1.0f;
                    denom[j + 1] = expf(yp[i + j + 1]) - 1.0f;
                    denom[j + 2] = expf(yp[i + j + 2]) - 1.0f;
                    denom[j + 3] = expf(yp[i + j + 3]) - 1.0f;
                }
                for (; j < vl; ++j) {
                    denom[j] = expf(yp[i + j]) - 1.0f;
                }

                vfloat32m8_t vx = __riscv_vle32_v_f32m8(xp + i, vl);
                vfloat32m8_t vd = __riscv_vle32_v_f32m8(denom, vl);
                vfloat32m8_t vw = __riscv_vfdiv_vv_f32m8(vx, vd, vl);

                __riscv_vse32_v_f32m8(wp + i, vw, vl);
                i += vl;
            }

            dummy(y, w, u, v, x, 0.0);
        }
    } else
#endif
    {
        for (int nl = 0; nl < iterations; nl++) {
            for (Index_type i = 0; i < LEN_1D; ++i) {
                y[i] = u[i] / v[i];
                w[i] = x[i] / ( expf(y[i]) - 1.0f );
            }
            dummy(y, w, u, v, x, 0.0);
        }
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

